import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n_str = input_data[0]
    e = int(input_data[1])

    target_val = 1 << e
    target_str = str(target_val)
    m = len(target_str)

    if m > len(n_str):
        print(0)
        return

    # Precompute powers of 10
    max_len = len(n_str) + 1
    pow10 = [1] * max_len
    for i in range(1, max_len):
        pow10[i] = pow10[i-1] * 10

    # Build KMP failure function (pi array)
    pi = [0] * m
    for i in range(1, m):
        j = pi[i-1]
        while j > 0 and target_str[i] != target_str[j]:
            j = pi[j-1]
        if target_str[i] == target_str[j]:
            j += 1
        pi[i] = j

    # Memoization table: (index, state, tight, started)
    # index: current digit position (0 to len(n_str))
    # state: current match length in KMP (0 to m-1)
    # tight: boolean, true if we are restricted by the prefix of n
    # started: boolean, true if we have started placing non-zero digits (to handle leading zeros)
    memo = {}

    def dp(idx, state, tight, started):
        if idx == len(n_str):
            return 1 if state == m else 0

        state_key = (idx, state, tight, started)
        if state_key in memo:
            return memo[state_key]

        limit = int(n_str[idx]) if tight else 9
        count = 0

        for digit in range(10):
            new_tight = tight and (digit == limit)
            new_started = started or (digit != 0)

            if not new_started:
                # Still in leading zeros, state remains 0
                count += dp(idx + 1, 0, new_tight, False)
            else:
                # Determine new KMP state
                if state == 0:
                    if target_str[0] == str(digit):
                        new_state = 1
                    else:
                        new_state = 0
                else:
                    # Try to extend the current match
                    j = state
                    while j > 0 and target_str[j] != str(digit):
                        j = pi[j-1]
                    if target_str[j] == str(digit):
                        j += 1
                    new_state = j

                if new_state == m:
                    # Match found! All remaining positions can be anything.
                    remaining = len(n_str) - (idx + 1)
                    count += pow10[remaining]
                else:
                    count += dp(idx + 1, new_state, new_tight, True)

        memo[state_key] = count
        return count

    # Start DP
    # idx=0, state=0, tight=True, started=False
    result = dp(0, 0, True, False)
    print(result)

if __name__ == "__main__":
    solve()
